import type { BetaRawMessageStreamEvent } from '@anthropic-ai/sdk/resources/beta/messages/messages.mjs'
import { randomUUID } from 'crypto'
import type { GeminiPart, GeminiStreamChunk } from './types.js'

export async function* adaptGeminiStreamToAnthropic(
  stream: AsyncIterable<GeminiStreamChunk>,
  model: string,
): AsyncGenerator<BetaRawMessageStreamEvent, void> {
  const messageId = `msg_${randomUUID().replace(/-/g, '').slice(0, 24)}`
  let started = false
  let stopped = false
  let nextContentIndex = 0
  let openTextLikeBlock:
    | { index: number; type: 'text' | 'thinking' }
    | null = null
  let sawToolUse = false
  let finishReason: string | undefined
  let inputTokens = 0
  let outputTokens = 0

  for await (const chunk of stream) {
    const usage = chunk.usageMetadata
    if (usage) {
      inputTokens = usage.promptTokenCount ?? inputTokens
      outputTokens =
        (usage.candidatesTokenCount ?? 0) + (usage.thoughtsTokenCount ?? 0)
    }

    if (!started) {
      started = true
      yield {
        type: 'message_start',
        message: {
          id: messageId,
          type: 'message',
          role: 'assistant',
          content: [],
          model,
          container: null,
          context_management: null,
          diagnostics: null,
          stop_details: null,
          stop_reason: null,
          stop_sequence: null,
          usage: {
            input_tokens: inputTokens,
            output_tokens: 0,
            cache_creation_input_tokens: 0,
            cache_read_input_tokens: 0,
          },
        },
      } as BetaRawMessageStreamEvent
    }

    const candidate = chunk.candidates?.[0]
    const parts = candidate?.content?.parts ?? []

    for (const part of parts) {
      if (part.functionCall) {
        if (openTextLikeBlock) {
          yield {
            type: 'content_block_stop',
            index: openTextLikeBlock.index,
          } as BetaRawMessageStreamEvent
          openTextLikeBlock = null
        }

        sawToolUse = true
        const toolIndex = nextContentIndex++
        const toolId = `toolu_${randomUUID().replace(/-/g, '').slice(0, 24)}`
        yield {
          type: 'content_block_start',
          index: toolIndex,
          content_block: {
            type: 'tool_use',
            id: toolId,
            name: part.functionCall.name || '',
            input: {},
          },
        } as BetaRawMessageStreamEvent

        if (part.thoughtSignature) {
          yield {
            type: 'content_block_delta',
            index: toolIndex,
            delta: {
              type: 'signature_delta',
              signature: part.thoughtSignature,
            },
          } as BetaRawMessageStreamEvent
        }

        if (part.functionCall.args && Object.keys(part.functionCall.args).length > 0) {
          yield {
            type: 'content_block_delta',
            index: toolIndex,
            delta: {
              type: 'input_json_delta',
              partial_json: JSON.stringify(part.functionCall.args),
            },
          } as BetaRawMessageStreamEvent
        }

        yield {
          type: 'content_block_stop',
          index: toolIndex,
        } as BetaRawMessageStreamEvent
        continue
      }

      const textLikeType = getTextLikeBlockType(part)
      if (textLikeType) {
        if (!openTextLikeBlock || openTextLikeBlock.type !== textLikeType) {
          if (openTextLikeBlock) {
            yield {
              type: 'content_block_stop',
              index: openTextLikeBlock.index,
            } as BetaRawMessageStreamEvent
          }

          openTextLikeBlock = {
            index: nextContentIndex++,
            type: textLikeType,
          }

          yield {
            type: 'content_block_start',
            index: openTextLikeBlock.index,
            content_block:
              textLikeType === 'thinking'
                ? {
                    type: 'thinking',
                    thinking: '',
                    signature: '',
                  }
                : {
                    type: 'text',
                    text: '',
                  },
          } as BetaRawMessageStreamEvent
        }

        if (part.text) {
          yield {
            type: 'content_block_delta',
            index: openTextLikeBlock.index,
            delta:
              textLikeType === 'thinking'
                ? {
                    type: 'thinking_delta',
                    thinking: part.text,
                  }
                : {
                    type: 'text_delta',
                    text: part.text,
                  },
          } as BetaRawMessageStreamEvent
        }

        if (part.thoughtSignature) {
          yield {
            type: 'content_block_delta',
            index: openTextLikeBlock.index,
            delta: {
              type: 'signature_delta',
              signature: part.thoughtSignature,
            },
          } as BetaRawMessageStreamEvent
        }

        continue
      }

      if (part.thoughtSignature && openTextLikeBlock) {
        yield {
          type: 'content_block_delta',
          index: openTextLikeBlock.index,
          delta: {
            type: 'signature_delta',
            signature: part.thoughtSignature,
          },
        } as BetaRawMessageStreamEvent
      }
    }

    if (candidate?.finishReason) {
      finishReason = candidate.finishReason
    }
  }

  if (!started) {
    return
  }

  if (openTextLikeBlock) {
    yield {
      type: 'content_block_stop',
      index: openTextLikeBlock.index,
    } as BetaRawMessageStreamEvent
  }

  if (!stopped) {
    yield {
      type: 'message_delta',
      delta: {
        stop_reason: mapGeminiFinishReason(finishReason, sawToolUse),
        stop_sequence: null,
      },
      usage: {
        output_tokens: outputTokens,
      },
    } as BetaRawMessageStreamEvent

    yield {
      type: 'message_stop',
    } as BetaRawMessageStreamEvent
    stopped = true
  }
}

function getTextLikeBlockType(
  part: GeminiPart,
): 'text' | 'thinking' | null {
  if (typeof part.text !== 'string') {
    return null
  }
  return part.thought ? 'thinking' : 'text'
}

function mapGeminiFinishReason(
  reason: string | undefined,
  sawToolUse: boolean,
): string {
  switch (reason) {
    case 'MAX_TOKENS':
      return 'max_tokens'
    case 'STOP':
    case 'FINISH_REASON_UNSPECIFIED':
    case 'SAFETY':
    case 'RECITATION':
    case 'BLOCKLIST':
    case 'PROHIBITED_CONTENT':
    case 'SPII':
    case 'MALFORMED_FUNCTION_CALL':
    default:
      return sawToolUse ? 'tool_use' : 'end_turn'
  }
}

import { logEvent } from '@thyrox/local-observability'
import { openBrowser } from '@thyrox/storage/browser.js'
import { AuthCodeListener } from './auth-code-listener.js'
import * as client from './client.js'
import * as crypto from './crypto.js'
import type {
  OAuthProfileResponse,
  OAuthTokenExchangeResponse,
  OAuthTokens,
  RateLimitTier,
  SubscriptionType,
} from './types.js'

// Codex OAuth — standalone module, no Anthropic dependency
export { runCodexOAuthFlow, refreshCodexToken, exchangeCodexCode, buildCodexAuthUrl, extractCodexAccountId } from './codex-client.js'
export type { CodexTokens } from './codex-client.js'
export { saveCodexOAuthTokens, getCodexOAuthTokens, checkAndRefreshCodexTokenIfNeeded } from './codex-auth.js'
export * from './codex-constants.js'

/**
 * OAuth service that handles the OAuth 2.0 authorization code flow with PKCE.
 *
 * Supports two ways to get authorization codes:
 * 1. Automatic: Opens browser, redirects to localhost where we capture the code
 * 2. Manual: User manually copies and pastes the code (used in non-browser environments)
 */
export class OAuthService {
  private codeVerifier: string
  private authCodeListener: AuthCodeListener | null = null
  private port: number | null = null
  private manualAuthCodeResolver: ((authorizationCode: string) => void) | null =
    null

  constructor() {
    this.codeVerifier = crypto.generateCodeVerifier()
  }

  async startOAuthFlow(
    authURLHandler: (url: string, automaticUrl?: string) => Promise<void>,
    options?: {
      loginWithClaudeAi?: boolean
      inferenceOnly?: boolean
      expiresIn?: number
      orgUUID?: string
      loginHint?: string
      loginMethod?: string
      /**
       * Don't call openBrowser(). Caller takes both URLs via authURLHandler
       * and decides how/where to open them. Used by the SDK control protocol
       * (claude_authenticate) where the SDK client owns the user's display,
       * not this process.
       */
      skipBrowserOpen?: boolean
    },
  ): Promise<OAuthTokens> {
    // Create OAuth callback listener and start it
    this.authCodeListener = new AuthCodeListener()
    this.port = await this.authCodeListener.start()

    // Generate PKCE values and state
    const codeChallenge = crypto.generateCodeChallenge(this.codeVerifier)
    const state = crypto.generateState()

    // Build auth URLs for both automatic and manual flows
    const opts = {
      codeChallenge,
      state,
      port: this.port,
      loginWithClaudeAi: options?.loginWithClaudeAi,
      inferenceOnly: options?.inferenceOnly,
      orgUUID: options?.orgUUID,
      loginHint: options?.loginHint,
      loginMethod: options?.loginMethod,
    }
    const manualFlowUrl = client.buildAuthUrl({ ...opts, isManual: true })
    const automaticFlowUrl = client.buildAuthUrl({ ...opts, isManual: false })

    // Wait for either automatic or manual auth code
    const authorizationCode = await this.waitForAuthorizationCode(
      state,
      async () => {
        if (options?.skipBrowserOpen) {
          // Hand both URLs to the caller. The automatic one still works
          // if the caller opens it on the same host (localhost listener
          // is running); the manual one works from anywhere.
          await authURLHandler(manualFlowUrl, automaticFlowUrl)
        } else {
          await authURLHandler(manualFlowUrl) // Show manual option to user
          await openBrowser(automaticFlowUrl) // Try automatic flow
        }
      },
    )

    // Check if the automatic flow is still active (has a pending response)
    const isAutomaticFlow = this.authCodeListener?.hasPendingResponse() ?? false
    logEvent('tengu_oauth_auth_code_received', { automatic: isAutomaticFlow })

    try {
      // Exchange authorization code for tokens
      const tokenResponse = await client.exchangeCodeForTokens(
        authorizationCode,
        state,
        this.codeVerifier,
        this.port!,
        !isAutomaticFlow, // Pass isManual=true if it's NOT automatic flow
        options?.expiresIn,
      )

      // Fetch profile info (subscription type and rate limit tier) for the
      // returned OAuthTokens. Logout and account storage are handled by the
      // caller (installOAuthTokens in auth.ts).
      const profileInfo = await client.fetchProfileInfo(
        tokenResponse.access_token,
      )

      // Handle success redirect for automatic flow
      if (isAutomaticFlow) {
        const scopes = client.parseScopes(tokenResponse.scope)
        this.authCodeListener?.handleSuccessRedirect(scopes)
      }

      return this.formatTokens(
        tokenResponse,
        profileInfo.subscriptionType,
        profileInfo.rateLimitTier,
        profileInfo.rawProfile,
      )
    } catch (error) {
      // If we have a pending response, send an error redirect before closing
      if (isAutomaticFlow) {
        this.authCodeListener?.handleErrorRedirect()
      }
      throw error
    } finally {
      // Always cleanup
      this.authCodeListener?.close()
    }
  }

  private async waitForAuthorizationCode(
    state: string,
    onReady: () => Promise<void>,
  ): Promise<string> {
    return new Promise((resolve, reject) => {
      // Set up manual auth code resolver
      this.manualAuthCodeResolver = resolve

      // Start automatic flow
      this.authCodeListener
        ?.waitForAuthorization(state, onReady)
        .then(authorizationCode => {
          this.manualAuthCodeResolver = null
          resolve(authorizationCode)
        })
        .catch(error => {
          this.manualAuthCodeResolver = null
          reject(error)
        })
    })
  }

  // Handle manual flow callback when user pastes the auth code
  handleManualAuthCodeInput(params: {
    authorizationCode: string
    state: string
  }): void {
    if (this.manualAuthCodeResolver) {
      this.manualAuthCodeResolver(params.authorizationCode)
      this.manualAuthCodeResolver = null
      // Close the auth code listener since manual input was used
      this.authCodeListener?.close()
    }
  }

  private formatTokens(
    response: OAuthTokenExchangeResponse,
    subscriptionType: SubscriptionType | null,
    rateLimitTier: RateLimitTier | null,
    profile?: OAuthProfileResponse,
  ): OAuthTokens {
    if (!response.refresh_token) {
      // El intercambio de código por token siempre devuelve refresh_token
      // (grant `authorization_code` con `offline_access`); esta guarda sólo
      // hace explícita esa garantía para el chequeo de tipos.
      throw new Error('OAuth token exchange response missing refresh_token')
    }
    return {
      accessToken: response.access_token,
      refreshToken: response.refresh_token,
      expiresAt: Date.now() + response.expires_in * 1000,
      scopes: client.parseScopes(response.scope),
      subscriptionType,
      rateLimitTier,
      profile,
      tokenAccount: response.account
        ? {
            uuid: response.account.uuid,
            emailAddress: response.account.email_address,
            organizationUuid: response.organization?.uuid,
          }
        : undefined,
    }
  }

  // Clean up any resources (like the local server)
  cleanup(): void {
    this.authCodeListener?.close()
    this.manualAuthCodeResolver = null
  }
}

/**
 * Envoltura del SDK de OpenAI — porte de
 * `ccnmt: packages/provider/src/openai/client.ts` (81 lineas, 2 exports).
 *
 * El puerto es COMPLETO: `getOpenAIClient` y `clearOpenAIClientCache`, las dos
 * exportaciones de la fuente, mas su cache de modulo. Ninguna queda fuera.
 *
 * Los casts `as any` sobre `fetchOptions` y `fetch` son un rodeo del sistema
 * de tipos POR DISENO, y viajan del original: las opciones del SDK admiten en
 * ejecucion tanto la interfaz de fetch de Node como la de la web, pero sus
 * tipos publicados fijan una sola variante. Es compatibilidad de version del
 * SDK, no descuido.
 *
 * El paquete `openai` NO estaba en el arbol al empezar este porte; se declaro
 * como dependencia de este paquete (`^6.33.0`, el mismo rango que la fuente
 * declara en su raiz) en vez de reimplementar el cliente HTTP. Portar el
 * modulo sin su SDK habria sido portar otra cosa.
 */
import OpenAI from 'openai'
import { readEnv } from '@thyrox/config/env/utils'
import { getProviderNetworkLayer } from '../network.js'
import { resolveConnectionForModel } from '../providers.js'

/**
 * El registro de conexiones es la fuente de verdad del endpoint y la clave.
 * Cuando una conexion coincide con el modelo pedido, SU endpoint y SU clave
 * ganan sobre las variables de entorno — asi es como conviven varios
 * proveedores compatibles con OpenAI (Ollama, DeepSeek y vLLM, cada uno con su
 * conexion).
 *
 * El respaldo por entorno es el modo heredado de proveedor unico:
 *
 * - `OPENAI_API_KEY`    obligatoria; la clave.
 * - `OPENAI_BASE_URL`   recomendada; la URL base.
 * - `OPENAI_ORG_ID`     opcional.
 * - `OPENAI_PROJECT_ID` opcional.
 */

// Cache por id de conexion —o por la clave del respaldo por entorno— para que
// varias conexiones no se pisen un unico cliente compartido. Cambiar de modelo
// dispara una resolucion nueva; el cliente viejo se recolecta si nadie lo
// referencia.
const clientCache = new Map<string, OpenAI>()

export function getOpenAIClient(options?: {
  maxRetries?: number
  fetchOverride?: unknown
  source?: string
  /** Id del modelo — sirve para resolver el endpoint y la clave de su conexion. */
  model?: string
}): OpenAI {
  const networkLayer = getProviderNetworkLayer()

  const conn = options?.model ? resolveConnectionForModel(options.model) : undefined
  const usingConn = conn?.protocol === 'openai' && conn.auth.type === 'api_key'

  const apiKey = usingConn
    ? conn.auth.type === 'api_key'
      ? conn.auth.key
      : ''
    : readEnv('OPENAI_API_KEY') || ''
  const baseURL = usingConn ? conn.endpoint : readEnv('OPENAI_BASE_URL')

  // Clave de cache: `conn:<id>` para los clientes por conexion, `env` para el
  // respaldo. `fetchOverride` desactiva la cache — es la costura de prueba.
  const cacheKey = usingConn && conn ? `conn:${conn.id}` : 'env'
  if (!options?.fetchOverride) {
    const cached = clientCache.get(cacheKey)
    if (cached) return cached
  }

  const client = new OpenAI({
    apiKey,
    ...(baseURL && { baseURL }),
    maxRetries: options?.maxRetries ?? 0,
    timeout: parseInt(readEnv('API_TIMEOUT_MS') || String(600 * 1000), 10),
    dangerouslyAllowBrowser: true,
    ...(readEnv('OPENAI_ORG_ID') && { organization: readEnv('OPENAI_ORG_ID') }),
    ...(readEnv('OPENAI_PROJECT_ID') && { project: readEnv('OPENAI_PROJECT_ID') }),
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    fetchOptions: networkLayer.getProxyFetchOptions({ forAnthropicAPI: false }) as any,
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    ...(options?.fetchOverride ? { fetch: options.fetchOverride as any } : {}),
  })

  if (!options?.fetchOverride) {
    clientCache.set(cacheKey, client)
  }

  return client
}

/** Vacia los clientes cacheados; util cuando las conexiones cambian en caliente. */
export function clearOpenAIClientCache(): void {
  clientCache.clear()
}

/**
 * OpenAI stream adapter — SDK-to-SDK shape translation. Heavy `as any`
 * usage is by-design type-system bypass: OpenAI extensions like
 * `prompt_tokens_details` and `reasoning_content` are runtime fields
 * not in the published `ChatCompletionChunk` types.
 */
import type { BetaRawMessageStreamEvent } from '@anthropic-ai/sdk/resources/beta/messages/messages.mjs'
import type { ChatCompletionChunk } from 'openai/resources/chat/completions/completions.mjs'
import { randomUUID } from 'crypto'

/**
 * Adapt an OpenAI streaming response into Anthropic BetaRawMessageStreamEvent.
 *
 * Mapping:
 *   First chunk              → message_start
 *   delta.reasoning_content  → content_block_start(thinking) + thinking_delta + content_block_stop
 *   delta.content            → content_block_start(text) + text_delta + content_block_stop
 *   delta.tool_calls         → content_block_start(tool_use) + input_json_delta + content_block_stop
 *   finish_reason            → message_delta(stop_reason) + message_stop
 *   usage.cached_tokens      → cache_read_input_tokens in message_start usage
 *
 * Thinking support:
 *   DeepSeek and compatible providers send `delta.reasoning_content` for chain-of-thought.
 *   This is mapped to Anthropic's `thinking` content blocks:
 *     content_block_start: { type: 'thinking', thinking: '', signature: '' }
 *     content_block_delta: { type: 'thinking_delta', thinking: '...' }
 *
 * Prompt caching:
 *   OpenAI reports cached tokens in usage.prompt_tokens_details.cached_tokens.
 *   This is mapped to Anthropic's cache_read_input_tokens.
 */
export async function* adaptOpenAIStreamToAnthropic(
  stream: AsyncIterable<ChatCompletionChunk>,
  model: string,
): AsyncGenerator<BetaRawMessageStreamEvent, void> {
  const messageId = `msg_${randomUUID().replace(/-/g, '').slice(0, 24)}`

  let started = false
  let currentContentIndex = -1

  // Track tool_use blocks: tool_calls index → { contentIndex, id, name, arguments }
  const toolBlocks = new Map<number, { contentIndex: number; id: string; name: string; arguments: string }>()

  // Track thinking block state
  let thinkingBlockOpen = false

  // Track text block state
  let textBlockOpen = false

  // Track usage
  let inputTokens = 0
  let outputTokens = 0
  let cachedTokens = 0

  // Track all open content block indices (for cleanup)
  const openBlockIndices = new Set<number>()

  for await (const chunk of stream) {
    const choice = chunk.choices?.[0]
    const delta = choice?.delta

    // Extract usage from any chunk that carries it
    if (chunk.usage) {
      inputTokens = chunk.usage.prompt_tokens ?? inputTokens
      outputTokens = chunk.usage.completion_tokens ?? outputTokens
      // OpenAI prompt caching: prompt_tokens_details.cached_tokens
      const details = (chunk.usage as any).prompt_tokens_details
      if (details?.cached_tokens) {
        cachedTokens = details.cached_tokens
      }
    }

    // Emit message_start on first chunk
    if (!started) {
      started = true

      yield {
        type: 'message_start',
        message: {
          id: messageId,
          type: 'message',
          role: 'assistant',
          content: [],
          container: null,
          context_management: null,
          diagnostics: null,
          model,
          stop_details: null,
          stop_reason: null,
          stop_sequence: null,
          usage: {
            input_tokens: inputTokens,
            output_tokens: 0,
            cache_creation_input_tokens: 0,
            cache_read_input_tokens: cachedTokens,
          },
        },
      } as BetaRawMessageStreamEvent
    }

    if (!delta) continue

    // Handle reasoning_content → Anthropic thinking block
    // DeepSeek and compatible providers send delta.reasoning_content
    const reasoningContent = (delta as any).reasoning_content
    if (reasoningContent != null && reasoningContent !== '') {
      if (!thinkingBlockOpen) {
        currentContentIndex++
        thinkingBlockOpen = true
        openBlockIndices.add(currentContentIndex)

        yield {
          type: 'content_block_start',
          index: currentContentIndex,
          content_block: {
            type: 'thinking',
            thinking: '',
            signature: '',
          },
        } as BetaRawMessageStreamEvent
      }

      yield {
        type: 'content_block_delta',
        index: currentContentIndex,
        delta: {
          type: 'thinking_delta',
          thinking: reasoningContent,
        },
      } as BetaRawMessageStreamEvent
    }

    // Handle text content
    if (delta.content != null && delta.content !== '') {
      if (!textBlockOpen) {
        // Close thinking block if still open (reasoning done, now generating answer)
        if (thinkingBlockOpen) {
          yield {
            type: 'content_block_stop',
            index: currentContentIndex,
          } as BetaRawMessageStreamEvent
          openBlockIndices.delete(currentContentIndex)
          thinkingBlockOpen = false
        }

        currentContentIndex++
        textBlockOpen = true
        openBlockIndices.add(currentContentIndex)

        yield {
          type: 'content_block_start',
          index: currentContentIndex,
          content_block: {
            type: 'text',
            text: '',
          },
        } as BetaRawMessageStreamEvent
      }

      yield {
        type: 'content_block_delta',
        index: currentContentIndex,
        delta: {
          type: 'text_delta',
          text: delta.content,
        },
      } as BetaRawMessageStreamEvent
    }

    // Handle tool calls
    if (delta.tool_calls) {
      for (const tc of delta.tool_calls) {
        const tcIndex = tc.index

        if (!toolBlocks.has(tcIndex)) {
          // Close thinking block if open
          if (thinkingBlockOpen) {
            yield {
              type: 'content_block_stop',
              index: currentContentIndex,
            } as BetaRawMessageStreamEvent
            openBlockIndices.delete(currentContentIndex)
            thinkingBlockOpen = false
          }

          // Close text block if open
          if (textBlockOpen) {
            yield {
              type: 'content_block_stop',
              index: currentContentIndex,
            } as BetaRawMessageStreamEvent
            openBlockIndices.delete(currentContentIndex)
            textBlockOpen = false
          }

          // Start new tool_use block
          currentContentIndex++
          const toolId = tc.id || `toolu_${randomUUID().replace(/-/g, '').slice(0, 24)}`
          const toolName = tc.function?.name || ''

          toolBlocks.set(tcIndex, {
            contentIndex: currentContentIndex,
            id: toolId,
            name: toolName,
            arguments: '',
          })
          openBlockIndices.add(currentContentIndex)

          yield {
            type: 'content_block_start',
            index: currentContentIndex,
            content_block: {
              type: 'tool_use',
              id: toolId,
              name: toolName,
              input: {},
            },
          } as BetaRawMessageStreamEvent
        }

        // Stream argument fragments
        const argFragment = tc.function?.arguments
        if (argFragment) {
          toolBlocks.get(tcIndex)!.arguments += argFragment
          yield {
            type: 'content_block_delta',
            index: toolBlocks.get(tcIndex)!.contentIndex,
            delta: {
              type: 'input_json_delta',
              partial_json: argFragment,
            },
          } as BetaRawMessageStreamEvent
        }
      }
    }

    // Handle finish
    if (choice?.finish_reason) {
      // Close thinking block if still open
      if (thinkingBlockOpen) {
        yield {
          type: 'content_block_stop',
          index: currentContentIndex,
        } as BetaRawMessageStreamEvent
        openBlockIndices.delete(currentContentIndex)
        thinkingBlockOpen = false
      }

      // Close text block if still open
      if (textBlockOpen) {
        yield {
          type: 'content_block_stop',
          index: currentContentIndex,
        } as BetaRawMessageStreamEvent
        openBlockIndices.delete(currentContentIndex)
        textBlockOpen = false
      }

      // Close all tool blocks that haven't been closed yet
      for (const [, block] of toolBlocks) {
        if (openBlockIndices.has(block.contentIndex)) {
          yield {
            type: 'content_block_stop',
            index: block.contentIndex,
          } as BetaRawMessageStreamEvent
          openBlockIndices.delete(block.contentIndex)
        }
      }

      // Map finish_reason to Anthropic stop_reason.
      // Some backends return "stop" even when tool_calls are present —
      // force "tool_use" when we saw any tool blocks to ensure the query
      // loop actually executes the tools.
      const hasToolCalls = toolBlocks.size > 0
      const stopReason = hasToolCalls ? 'tool_use' : mapFinishReason(choice.finish_reason)

      yield {
        type: 'message_delta',
        delta: {
          stop_reason: stopReason,
          stop_sequence: null,
        },
        usage: {
          output_tokens: outputTokens,
        },
      } as BetaRawMessageStreamEvent

      yield {
        type: 'message_stop',
      } as BetaRawMessageStreamEvent
    }
  }

  // Safety: close any remaining open blocks if stream ended without finish_reason
  for (const idx of openBlockIndices) {
    yield {
      type: 'content_block_stop',
      index: idx,
    } as BetaRawMessageStreamEvent
  }
}

/**
 * Map OpenAI finish_reason to Anthropic stop_reason.
 *
 * stop           → end_turn
 * tool_calls     → tool_use
 * length         → max_tokens
 * content_filter → end_turn
 */
function mapFinishReason(reason: string): string {
  switch (reason) {
    case 'stop':
      return 'end_turn'
    case 'tool_calls':
      return 'tool_use'
    case 'length':
      return 'max_tokens'
    case 'content_filter':
      return 'end_turn'
    default:
      return 'end_turn'
  }
}

/**
 * Porte COMPLETO de `ccnmt: packages/provider/src/proxy.ts` — sus 13
 * exportaciones, ninguna omitida. Autocontenido salvo `./caCerts.js` y
 * `./mtls.js`, ambos resueltos dentro de este mismo paquete.
 */

import axios, { type AxiosInstance } from 'axios'
import type { LookupOptions } from 'node:dns'
import { BlockList, isIP } from 'node:net'
import type { Agent } from 'node:http'
import { HttpsProxyAgent, type HttpsProxyAgentOptions } from 'https-proxy-agent'
import memoize from 'lodash-es/memoize.js'
import type * as undici from 'undici'
import { getAllEnv, isEnvTruthy, readEnv } from '@thyrox/config/env/utils'
import { logForDebugging } from '@thyrox/local-observability/debug.js'
import { getCACertificates } from './internal/caCerts.ts'
import { getMTLSAgent, getMTLSConfig, getTLSFetchOptions, type TLSConfig } from './mtls.ts'

let keepAliveDisabled = false

export function disableKeepAlive(): void {
  keepAliveDisabled = true
}

export function _resetKeepAliveForTesting(): void {
  keepAliveDisabled = false
}

/** Convierte `dns.LookupOptions.family` a un valor numérico de familia. */
export function getAddressFamily(options: LookupOptions): 0 | 4 | 6 {
  switch (options.family) {
    case 0:
    case 4:
    case 6:
      return options.family
    case 'IPv6':
      return 6
    case 'IPv4':
    case undefined:
      return 4
    default:
      throw new Error(`Unsupported address family: ${options.family}`)
  }
}

type EnvLike = Record<string, string | undefined>

/**
 * URL de proxy activa, elegida POR PROTOCOLO del destino.
 *
 * Con `targetUrl` declarado, un destino `http://` recibe el proxy de http y
 * uno `https://` el de https. Sin él —que es como los consumidores de hoy la
 * llaman— se conserva la precedencia anterior: https antes que http.
 *
 * `ALL_PROXY` es el respaldo de ambos caminos. No se leía en NINGÚN archivo
 * de este árbol antes de TASK-THYROX-0187 (medido: 0), asi que un entorno
 * que sólo lo declarara salía sin proxy.
 *
 * La forma se adapta de `omniroute: open-sse/utils/proxyFetch.ts:502-526`
 * (MIT). DIVERGENCIA declarada en la precedencia de caja: la referencia pone
 * la MAYÚSCULA primero y aquí gana la minúscula, que es lo que `getNoProxy`
 * ya hace y lo que curl documenta. Cambiarlo alteraría el comportamiento de
 * un entorno que declare las dos con valores distintos.
 *
 * Una `targetUrl` que no parsea cae al camino sin destino en vez de reventar:
 * el llamador pregunta por el proxy, no por la validez de su URL.
 *
 * Un protocolo que no es `https:` toma la cadena de http — el ternario de la
 * referencia, portado. No es un descuido suyo sobre `wss:`: medido quien
 * llama a `resolveEnvProxyUrl` (`proxyFallback.ts:206`, `proxyFetch.ts:552`)
 * y a `resolveProxyForRequest` (`tlsClientProxy.ts:21`, `proxyFetch.ts:779`),
 * su poblacion es la del camino de fetch y TLS; el websocket de la referencia
 * viaja por otro camino (`executors/uc/ws.ts`) y nunca llega al ternario. El
 * eje es «es https», no «es TLS», y esa es la forma, no un efecto colateral.
 * TASK-THYROX-0191.
 */
export function getProxyUrl(
  env: EnvLike = getAllEnv(),
  targetUrl?: string,
): string | undefined {
  const anyProxy = env.all_proxy || env.ALL_PROXY

  if (targetUrl !== undefined) {
    let protocol: string | undefined
    try {
      protocol = new URL(targetUrl).protocol
    } catch {
      protocol = undefined
    }
    if (protocol !== undefined) {
      return protocol === 'https:'
        ? env.https_proxy || env.HTTPS_PROXY || anyProxy
        : env.http_proxy || env.HTTP_PROXY || anyProxy
    }
  }

  return env.https_proxy || env.HTTPS_PROXY || env.http_proxy || env.HTTP_PROXY || anyProxy
}

/** Valor de NO_PROXY (minúscula gana sobre MAYÚSCULA). */
export function getNoProxy(env: EnvLike = getAllEnv()): string | undefined {
  return env.no_proxy || env.NO_PROXY
}

/**
 * ¿El nombre de host casa un patrón con comodín?
 *
 * Escaneo lineal, no `RegExp` compuesto: un patrón de `NO_PROXY` es entrada
 * no confiable, y componer una expresión regular desde ella admite ReDoS. La
 * forma se adapta de `omniroute: open-sse/utils/proxyFetch.ts:449` (MIT), que
 * declara esa misma razón en su comentario.
 */
function matchesGlobPattern(hostname: string, pattern: string): boolean {
  const segments = pattern.split('*')
  if (!hostname.startsWith(segments[0]!)) return false

  let cursor = segments[0]!.length
  for (let index = 1; index < segments.length; index++) {
    const segment = segments[index]!
    if (index === segments.length - 1) {
      // El último segmento ancla al final; vacío significa «cualquier cola».
      if (segment === '') return true
      return hostname.endsWith(segment) && hostname.length - segment.length >= cursor
    }
    const found = segment ? hostname.indexOf(segment, cursor) : cursor
    if (found === -1) return false
    cursor = found + segment.length
  }
  return true
}

/**
 * ¿La dirección cae dentro del bloque CIDR declarado?
 *
 * **Divergencia declarada frente a la referencia.** Ni
 * `ccnmt: packages/provider/src/proxy.ts` ni
 * `omniroute: open-sse/utils/proxyFetch.ts:422` leen CIDR: aquélla lo ignora,
 * y ésta cubre los rangos privados con una lista paralela codificada a mano
 * (`isLocalAddress`, `:480`). Esa lista es un segundo significante para el
 * mismo significado y puede divergir de lo que el entorno declaró; aquí se lee
 * el bloque tal como viene en `NO_PROXY`.
 *
 * **Ciega a IPv6.** Un bloque como `fc00::/7` devuelve `false`, no un error:
 * la lista de este entorno declara `::1` y `::` como hosts literales, que el
 * camino de host exacto ya cubre. Su cierre es TASK-THYROX-0188.
 */
/** Retira los corchetes con que una URL envuelve un literal IPv6. */
function stripIpv6Brackets(host: string): string {
  return host.startsWith('[') && host.endsWith(']') ? host.slice(1, -1) : host
}

function matchesCidrBlock(hostname: string, pattern: string): boolean {
  const slashAt = pattern.indexOf('/')
  if (slashAt === -1) return false

  const blockAddress = pattern.slice(0, slashAt)
  const prefixLength = Number(pattern.slice(slashAt + 1))
  if (!Number.isInteger(prefixLength) || prefixLength < 0) return false

  // La familia la decide `node:net`, no la forma de la cadena. La referencia
  // que este archivo ya cita —`golang.org/x/net/http/httpproxy`— resuelve el
  // bloque con `net.ParseCIDR`, que cubre las dos familias; `isIP` es su
  // equivalente en este stack y devuelve 4, 6 o 0.
  const blockFamily = isIP(blockAddress)
  const hostFamily = isIP(hostname)
  if (blockFamily === 0 || hostFamily === 0) return false

  const maxPrefix = blockFamily === 4 ? 32 : 128
  if (prefixLength > maxPrefix) return false

  // `BlockList` es el mecanismo de Node para esto, asi que no se escribe una
  // segunda aritmetica de mascara: la de 32 bits que vivia aqui no se podia
  // extender a 128 sin BigInt, y una implementacion propia de la comparacion
  // es una segunda fuente de verdad que nadie mantiene contra el stack.
  //
  // Un bloque IPv4 SI casa una direccion IPv4-mapeada (`::ffff:127.0.0.1`
  // contra `127.0.0.0/8` da true, medido). Es la conducta de `BlockList` y
  // coincide con el `ParseIP().To4()` de la referencia: se adopta, no se
  // corrige.
  const block = new BlockList()
  block.addSubnet(blockAddress, prefixLength, blockFamily === 4 ? 'ipv4' : 'ipv6')
  try {
    return block.check(hostname, hostFamily === 4 ? 'ipv4' : 'ipv6')
  } catch {
    // `check` lanza ante una direccion que `isIP` acepto y el mas no: se lee
    // como «no casa», nunca como «casa», porque el fallo abierto aqui manda
    // trafico fuera del proxy que el operador declaro.
    return false
  }
}

/** ¿Una URL debe saltarse el proxy según NO_PROXY? */
export function shouldBypassProxy(urlString: string, noProxy: string | undefined = getNoProxy()): boolean {
  if (!noProxy) return false
  if (noProxy === '*') return true

  try {
    const url = new URL(urlString)
    // `URL.hostname` CONSERVA los corchetes de un literal IPv6 — medido:
    // `new URL('http://[::1]:8080').hostname` da `'[::1]'`, e `isIP` sobre esa
    // forma devuelve 0. Toda comparacion de IP de aqui abajo trabaja sobre el
    // host desnudo. La idea se adopta de `omniroute: src/shared/network/
    // privateHost.ts::normalizeHost`; su regex vendorizada NO se porta, porque
    // existe alli para esquivar un `node:net` que rompia su bundle de
    // navegador — un problema que este arbol no tiene.
    const hostname = stripIpv6Brackets(url.hostname.toLowerCase())
    const port = url.port || (url.protocol === 'https:' ? '443' : '80')
    const hostWithPort = `${hostname}:${port}`

    const noProxyList = noProxy.split(/[,\s]+/).filter(Boolean)

    return noProxyList.some(rawPattern => {
      const pattern = rawPattern.toLowerCase().trim()

      // El CIDR se resuelve ANTES que el par `host:puerto`: un bloque IPv6
      // lleva dos puntos y la rama de puerto lo leería como un host.
      if (pattern.includes('/')) {
        return matchesCidrBlock(hostname, pattern)
      }
      // Un literal IPv6 desnudo (`::1`, `fd00::1`) lleva dos puntos y la rama
      // de `host:puerto` lo leia como tal: `'::1:8080' === '::1'` es falso, asi
      // que NUNCA casaba. `isIP` separa las dos formas — un `host:puerto` no es
      // una IP valida y da 0.
      if (isIP(pattern) === 6) {
        return hostname === pattern
      }
      if (pattern.includes(':')) {
        return hostWithPort === pattern
      }
      if (pattern.includes('*')) {
        return matchesGlobPattern(hostname, pattern)
      }
      if (pattern.startsWith('.')) {
        return hostname === pattern.substring(1) || hostname.endsWith(pattern)
      }
      // Un patrón desnudo cubre el dominio y todo lo que cuelgue de él, que es
      // la convención de curl y de `golang.org/x/net/http/httpproxy`. La
      // referencia exigía igualdad exacta, así que `example.com` no cubría
      // `api.example.com`: divergencia declarada, no porte parcial.
      return hostname === pattern || hostname.endsWith(`.${pattern}`)
    })
  } catch {
    return false
  }
}

function createHttpsProxyAgent(
  proxyUrl: string,
  extra: HttpsProxyAgentOptions = {},
): HttpsProxyAgent {
  const mtlsConfig = getMTLSConfig()
  const caCerts = getCACertificates()

  const agentOptions: HttpsProxyAgentOptions<string> = {
    ...(mtlsConfig && {
      cert: mtlsConfig.cert,
      key: mtlsConfig.key,
      passphrase: mtlsConfig.passphrase,
    }),
    ...(caCerts && { ca: caCerts }),
  }

  if (isEnvTruthy(readEnv('CLAUDE_CODE_PROXY_RESOLVES_HOSTS'))) {
    agentOptions.lookup = (hostname, options, callback) => {
      callback(null, hostname, getAddressFamily(options))
    }
  }

  return new HttpsProxyAgent(proxyUrl, { ...agentOptions, ...extra })
}

/** Instancia de axios con su propio agente de proxy. */
export function createAxiosInstance(extra: HttpsProxyAgentOptions = {}): AxiosInstance {
  const proxyUrl = getProxyUrl()
  const mtlsAgent = getMTLSAgent()
  const instance = axios.create({ proxy: false })

  if (!proxyUrl) {
    if (mtlsAgent) instance.defaults.httpsAgent = mtlsAgent
    return instance
  }

  const proxyAgent = createHttpsProxyAgent(proxyUrl, extra)
  instance.interceptors.request.use(config => {
    if (config.url && shouldBypassProxy(config.url)) {
      config.httpsAgent = mtlsAgent
      config.httpAgent = mtlsAgent
    } else {
      config.httpsAgent = proxyAgent
      config.httpAgent = proxyAgent
    }
    return config
  })
  return instance
}

/** Agente de proxy memoizado para la URI dada. */
export const getProxyAgent = memoize((uri: string): undici.Dispatcher => {
  // eslint-disable-next-line @typescript-eslint/no-require-imports
  const undiciMod = require('undici') as typeof undici
  const mtlsConfig = getMTLSConfig()
  const caCerts = getCACertificates()

  const proxyOptions: undici.EnvHttpProxyAgent.Options & {
    requestTls?: {
      cert?: string | Buffer
      key?: string | Buffer
      passphrase?: string
      ca?: string | string[] | Buffer
    }
  } = {
    httpProxy: uri,
    httpsProxy: uri,
    noProxy: readEnv('NO_PROXY') || readEnv('no_proxy'),
  }

  if (mtlsConfig || caCerts) {
    const tlsOpts = {
      ...(mtlsConfig && {
        cert: mtlsConfig.cert,
        key: mtlsConfig.key,
        passphrase: mtlsConfig.passphrase,
      }),
      ...(caCerts && { ca: caCerts }),
    }
    proxyOptions.connect = tlsOpts
    proxyOptions.requestTls = tlsOpts
  }

  return new undiciMod.EnvHttpProxyAgent(proxyOptions)
})

/** Agente HTTP configurado para soporte de proxy en WebSocket. */
export function getWebSocketProxyAgent(url: string): Agent | undefined {
  const proxyUrl = getProxyUrl()
  if (!proxyUrl) return undefined
  if (shouldBypassProxy(url)) return undefined
  return createHttpsProxyAgent(proxyUrl)
}

/** URL de proxy para conexiones WebSocket bajo Bun. */
export function getWebSocketProxyUrl(url: string): string | undefined {
  const proxyUrl = getProxyUrl()
  if (!proxyUrl) return undefined
  if (shouldBypassProxy(url)) return undefined
  return proxyUrl
}

/** Opciones de fetch para el SDK de Anthropic con proxy y mTLS. */
export function getProxyFetchOptions(opts?: { forAnthropicAPI?: boolean }): {
  tls?: TLSConfig
  dispatcher?: undici.Dispatcher
  proxy?: string
  unix?: string
  keepalive?: false
} {
  const base = keepAliveDisabled ? ({ keepalive: false } as const) : {}

  if (opts?.forAnthropicAPI) {
    const unixSocket = readEnv('ANTHROPIC_UNIX_SOCKET')
    if (unixSocket && typeof Bun !== 'undefined') {
      return { ...base, unix: unixSocket }
    }
  }

  const proxyUrl = getProxyUrl()

  if (proxyUrl) {
    if (typeof Bun !== 'undefined') {
      return { ...base, proxy: proxyUrl, ...getTLSFetchOptions() }
    }
    return { ...base, dispatcher: getProxyAgent(proxyUrl) }
  }

  return { ...base, ...getTLSFetchOptions() }
}

let proxyInterceptorId: number | undefined

/** Configura agentes HTTP globales tanto para axios como para undici. */
export function configureGlobalAgents(): void {
  const proxyUrl = getProxyUrl()
  const mtlsAgent = getMTLSAgent()

  if (proxyInterceptorId !== undefined) {
    axios.interceptors.request.eject(proxyInterceptorId)
    proxyInterceptorId = undefined
  }

  axios.defaults.proxy = undefined
  axios.defaults.httpAgent = undefined
  axios.defaults.httpsAgent = undefined

  if (proxyUrl) {
    axios.defaults.proxy = false

    const proxyAgent = createHttpsProxyAgent(proxyUrl)

    proxyInterceptorId = axios.interceptors.request.use(config => {
      if (config.url && shouldBypassProxy(config.url)) {
        if (mtlsAgent) {
          config.httpsAgent = mtlsAgent
          config.httpAgent = mtlsAgent
        } else {
          delete config.httpsAgent
          delete config.httpAgent
        }
      } else {
        config.httpsAgent = proxyAgent
        config.httpAgent = proxyAgent
      }
      return config
    })

    // eslint-disable-next-line @typescript-eslint/no-require-imports
    ;(require('undici') as typeof undici).setGlobalDispatcher(getProxyAgent(proxyUrl))
  } else if (mtlsAgent) {
    axios.defaults.httpsAgent = mtlsAgent

    const mtlsOptions = getTLSFetchOptions()
    if (mtlsOptions.dispatcher) {
      // eslint-disable-next-line @typescript-eslint/no-require-imports
      ;(require('undici') as typeof undici).setGlobalDispatcher(mtlsOptions.dispatcher)
    }
  }
}

/** Configuración de cliente AWS SDK con soporte de proxy. */
export async function getAWSClientProxyConfig(): Promise<object> {
  const proxyUrl = getProxyUrl()
  if (!proxyUrl) return {}

  const [{ NodeHttpHandler }, { defaultProvider }] = await Promise.all([
    import('@smithy/node-http-handler'),
    import('@aws-sdk/credential-provider-node'),
  ])

  const agent = createHttpsProxyAgent(proxyUrl)
  const requestHandler = new NodeHttpHandler({ httpAgent: agent, httpsAgent: agent })

  return {
    requestHandler,
    credentials: defaultProvider({ clientConfig: { requestHandler } }),
  }
}

/** Limpia la caché de agentes de proxy. */
export function clearProxyCache(): void {
  getProxyAgent.cache.clear?.()
  logForDebugging('Cleared proxy agent cache')
}

import type { UUID } from 'crypto'
import { getSessionId } from '@thyrox/app-host/bootstrap/state.js'
import type { ToolUseContext } from '@thyrox/tool-registry/Tool.js'
import {
  AGENT_COLORS,
  type AgentColorName,
} from '@thyrox/tool-registry/tools/AgentTool/agentColorManager.js'
import type {
  LocalJSXCommandContext,
  LocalJSXCommandOnDone,
} from '@thyrox/agent/command.js'
import {
  getTranscriptPath,
  saveAgentColor,
} from '@thyrox/storage/sessionStorage.js'
import { isTeammate } from '@thyrox/swarm/teammateState.js'

const RESET_ALIASES = ['default', 'reset', 'none', 'gray', 'grey'] as const

export async function call(
  onDone: LocalJSXCommandOnDone,
  context: ToolUseContext & LocalJSXCommandContext,
  args: string,
): Promise<null> {
  // Teammates cannot set their own color
  if (isTeammate()) {
    onDone(
      'Cannot set color: This session is a swarm teammate. Teammate colors are assigned by the team leader.',
      { display: 'system' },
    )
    return null
  }

  if (!args || args.trim() === '') {
    const colorList = AGENT_COLORS.join(', ')
    onDone(`Please provide a color. Available colors: ${colorList}, default`, {
      display: 'system',
    })
    return null
  }

  const colorArg = args.trim().toLowerCase()

  // Handle reset to default (gray)
  if (RESET_ALIASES.includes(colorArg as (typeof RESET_ALIASES)[number])) {
    const sessionId = getSessionId() as UUID
    const fullPath = getTranscriptPath()

    // Use "default" sentinel (not empty string) so truthiness guards
    // in sessionStorage.ts persist the reset across session restarts
    await saveAgentColor(sessionId, 'default', fullPath)

    context.setAppState(prev => ({
      ...prev,
      standaloneAgentContext: {
        ...prev.standaloneAgentContext,
        name: prev.standaloneAgentContext?.name ?? '',
        color: undefined,
      },
    }))

    onDone('Session color reset to default', { display: 'system' })
    return null
  }

  if (!AGENT_COLORS.includes(colorArg as AgentColorName)) {
    const colorList = AGENT_COLORS.join(', ')
    onDone(
      `Invalid color "${colorArg}". Available colors: ${colorList}, default`,
      { display: 'system' },
    )
    return null
  }

  const sessionId = getSessionId() as UUID
  const fullPath = getTranscriptPath()

  // Save to transcript for persistence across sessions
  await saveAgentColor(sessionId, colorArg, fullPath)

  // Update AppState for immediate effect
  context.setAppState(prev => ({
    ...prev,
    standaloneAgentContext: {
      ...prev.standaloneAgentContext,
      name: prev.standaloneAgentContext?.name ?? '',
      color: colorArg as AgentColorName,
    },
  }))

  onDone(`Session color set to: ${colorArg}`, { display: 'system' })
  return null
}

